-- =====================================================================
-- Pick Your Character - Blue Archive
-- 테이블 생성 스크립트 (Oracle 12c 이상)
--
-- * 클라이언트 문자셋이 UTF-8이어야 한글 CHECK 값이 깨지지 않는다.
-- * 생성 순서: 부모 → 자식. 다시 만들 때는 맨 아래 DROP 문을 먼저 실행한다.
-- * 11g에서는 GENERATED BY DEFAULT AS IDENTITY를 지우고 SEQUENCE를 쓴다.
-- * 허용값 목록(공격타입·방어타입·무기종류·머리색·눈색)은 구현 방식이
--   확정되지 않아 제약을 걸지 않았다. (명세서 10장 2번)
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. 회원
-- ---------------------------------------------------------------------
CREATE TABLE member (
  member_id       VARCHAR2(20 CHAR)                      NOT NULL,
  email           VARCHAR2(254 CHAR)                     NOT NULL,
  password_hash   VARCHAR2(255 CHAR)                     NOT NULL,
  member_grade    VARCHAR2(10 CHAR) DEFAULT 'MEMBER'     NOT NULL,
  account_status  VARCHAR2(10 CHAR) DEFAULT 'ACTIVE'     NOT NULL,
  joined_at       TIMESTAMP         DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_member        PRIMARY KEY (member_id),
  CONSTRAINT uq_member_email  UNIQUE (email),
  CONSTRAINT ck_member_grade  CHECK (member_grade IN ('MEMBER', 'ADMIN')),
  CONSTRAINT ck_member_status CHECK (account_status IN ('ACTIVE', 'WITHDRAWN'))
);


-- ---------------------------------------------------------------------
-- 2. 학교
-- ---------------------------------------------------------------------
CREATE TABLE school (
  school_id    NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  school_name  VARCHAR2(50 CHAR) NOT NULL,
  CONSTRAINT pk_school      PRIMARY KEY (school_id),
  CONSTRAINT uq_school_name UNIQUE (school_name)
);


-- ---------------------------------------------------------------------
-- 3. 동아리
-- ---------------------------------------------------------------------
CREATE TABLE club (
  club_id    NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  club_name  VARCHAR2(50 CHAR) NOT NULL,
  school_id  NUMBER(10)        NOT NULL,
  CONSTRAINT pk_club             PRIMARY KEY (club_id),
  CONSTRAINT uq_club_school_name UNIQUE (school_id, club_name),
  -- student의 복합 FK(club_id, school_id)가 참조할 대상
  CONSTRAINT uq_club_id_school   UNIQUE (club_id, school_id),
  CONSTRAINT fk_club_school      FOREIGN KEY (school_id) REFERENCES school (school_id)
);


-- ---------------------------------------------------------------------
-- 4. 학생
-- ---------------------------------------------------------------------
CREATE TABLE student (
  student_id     NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  name_ko        VARCHAR2(50 CHAR) NOT NULL,
  name_original  VARCHAR2(50 CHAR),
  grade          NUMBER(1),
  age            NUMBER(3),
  birthday       CHAR(5),
  height         NUMBER(3),
  voice_actor    VARCHAR2(50 CHAR),
  hair_color     VARCHAR2(20 CHAR),
  eye_color      VARCHAR2(20 CHAR),
  school_id      NUMBER(10)        NOT NULL,
  club_id        NUMBER(10),
  CONSTRAINT pk_student          PRIMARY KEY (student_id),
  CONSTRAINT ck_student_grade    CHECK (grade BETWEEN 1 AND 3),
  CONSTRAINT ck_student_age      CHECK (age > 0),
  CONSTRAINT ck_student_birthday CHECK (REGEXP_LIKE(birthday, '^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$')),
  CONSTRAINT ck_student_height   CHECK (height > 0),
  CONSTRAINT fk_student_school   FOREIGN KEY (school_id) REFERENCES school (school_id),
  -- 동아리가 학생의 학교에 속한 동아리인지 검사(요구 13). club_id가 NULL이면 검사하지 않는다.
  CONSTRAINT fk_student_club     FOREIGN KEY (club_id, school_id) REFERENCES club (club_id, school_id)
);


-- ---------------------------------------------------------------------
-- 5. 학생버전
-- ---------------------------------------------------------------------
CREATE TABLE student_version (
  version_id       NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  version_name     VARCHAR2(30 CHAR)   NOT NULL,
  display_name     VARCHAR2(60 CHAR)   NOT NULL,
  is_default       CHAR(1) DEFAULT 'N' NOT NULL,
  image_url        VARCHAR2(2000 BYTE),
  combat_role      VARCHAR2(10 CHAR)   NOT NULL,
  combat_position  VARCHAR2(10 CHAR)   NOT NULL,
  attack_type      VARCHAR2(10 CHAR)   NOT NULL,
  defense_type     VARCHAR2(10 CHAR)   NOT NULL,
  weapon_type      VARCHAR2(10 CHAR)   NOT NULL,
  student_id       NUMBER(10)          NOT NULL,
  CONSTRAINT pk_student_version      PRIMARY KEY (version_id),
  CONSTRAINT uq_version_display_name UNIQUE (display_name),
  CONSTRAINT uq_version_student_name UNIQUE (student_id, version_name),
  CONSTRAINT ck_version_is_default   CHECK (is_default IN ('Y', 'N')),
  CONSTRAINT ck_version_role         CHECK (combat_role IN ('스트라이커', '스페셜')),
  CONSTRAINT ck_version_position     CHECK (combat_position IN ('프론트', '미들', '백')),
  CONSTRAINT fk_version_student      FOREIGN KEY (student_id) REFERENCES student (student_id)
);

-- 학생당 기본 버전 최대 1개(요구 14). '최소 1개'는 앱에서 보장한다.
CREATE UNIQUE INDEX uq_version_default
  ON student_version (CASE WHEN is_default = 'Y' THEN student_id END);


-- ---------------------------------------------------------------------
-- 6. 대체명칭
-- ---------------------------------------------------------------------
CREATE TABLE alt_name (
  name_id     NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  name        VARCHAR2(50 CHAR) NOT NULL,
  name_type   VARCHAR2(10 CHAR) NOT NULL,
  student_id  NUMBER(10)        NOT NULL,
  CONSTRAINT pk_alt_name         PRIMARY KEY (name_id),
  CONSTRAINT uq_alt_name_student UNIQUE (student_id, name),
  CONSTRAINT ck_alt_name_type    CHECK (name_type IN ('번역명', '영문명', '애칭')),
  CONSTRAINT fk_alt_name_student FOREIGN KEY (student_id) REFERENCES student (student_id) ON DELETE CASCADE
);


-- ---------------------------------------------------------------------
-- 7. 좋아요 / 8. 즐겨찾기
-- ---------------------------------------------------------------------
CREATE TABLE version_like (
  member_id   VARCHAR2(20 CHAR)              NOT NULL,
  version_id  NUMBER(10)                     NOT NULL,
  created_at  TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_version_like PRIMARY KEY (member_id, version_id),
  CONSTRAINT fk_like_member  FOREIGN KEY (member_id)  REFERENCES member (member_id),
  CONSTRAINT fk_like_version FOREIGN KEY (version_id) REFERENCES student_version (version_id) ON DELETE CASCADE
);

CREATE TABLE version_favorite (
  member_id   VARCHAR2(20 CHAR)              NOT NULL,
  version_id  NUMBER(10)                     NOT NULL,
  created_at  TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_version_favorite PRIMARY KEY (member_id, version_id),
  CONSTRAINT fk_favorite_member  FOREIGN KEY (member_id)  REFERENCES member (member_id),
  CONSTRAINT fk_favorite_version FOREIGN KEY (version_id) REFERENCES student_version (version_id) ON DELETE CASCADE
);


-- ---------------------------------------------------------------------
-- 9. 이상형월드컵
-- ---------------------------------------------------------------------
CREATE TABLE worldcup (
  worldcup_id           NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  title                 VARCHAR2(100 CHAR)                     NOT NULL,
  topic                 VARCHAR2(500 CHAR),
  bracket_size          NUMBER(3)                              NOT NULL,
  visibility            VARCHAR2(10 CHAR) DEFAULT 'PRIVATE'    NOT NULL,
  composition_status    VARCHAR2(10 CHAR) DEFAULT 'DRAFT'      NOT NULL,
  created_at            TIMESTAMP         DEFAULT SYSTIMESTAMP NOT NULL,
  first_published_at    TIMESTAMP,
  is_manually_adjusted  CHAR(1)           DEFAULT 'N'          NOT NULL,
  member_id             VARCHAR2(20 CHAR)                      NOT NULL,
  CONSTRAINT pk_worldcup                  PRIMARY KEY (worldcup_id),
  CONSTRAINT ck_worldcup_bracket          CHECK (bracket_size IN (4, 8, 16, 32, 64, 128, 256)),
  CONSTRAINT ck_worldcup_visibility       CHECK (visibility IN ('PRIVATE', 'PUBLIC', 'DELETED')),
  CONSTRAINT ck_worldcup_composition      CHECK (composition_status IN ('DRAFT', 'CONFIRMED')),
  CONSTRAINT ck_worldcup_adjusted         CHECK (is_manually_adjusted IN ('Y', 'N')),
  -- 확정된 월드컵만 공개(요구 48)
  CONSTRAINT ck_worldcup_public_confirmed CHECK (visibility <> 'PUBLIC' OR composition_status = 'CONFIRMED'),
  CONSTRAINT ck_worldcup_public_published CHECK (visibility <> 'PUBLIC' OR first_published_at IS NOT NULL),
  CONSTRAINT fk_worldcup_member           FOREIGN KEY (member_id) REFERENCES member (member_id)
);


-- ---------------------------------------------------------------------
-- 10. 후보선별조건
-- ---------------------------------------------------------------------
CREATE TABLE candidate_filter (
  condition_id     NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  filter_item      VARCHAR2(20 CHAR) NOT NULL,
  condition_value  VARCHAR2(50 CHAR) NOT NULL,
  worldcup_id      NUMBER(10)        NOT NULL,
  CONSTRAINT pk_candidate_filter PRIMARY KEY (condition_id),
  CONSTRAINT uq_candidate_filter UNIQUE (worldcup_id, filter_item, condition_value),
  CONSTRAINT ck_filter_item      CHECK (filter_item IN ('SCHOOL', 'CLUB', 'GRADE', 'HAIR_COLOR', 'EYE_COLOR',
                                                        'ROLE', 'POSITION', 'ATTACK_TYPE', 'DEFENSE_TYPE',
                                                        'WEAPON_TYPE', 'DEFAULT_ONLY')),
  CONSTRAINT fk_filter_worldcup  FOREIGN KEY (worldcup_id) REFERENCES worldcup (worldcup_id)
);


-- ---------------------------------------------------------------------
-- 11. 월드컵후보
-- ---------------------------------------------------------------------
CREATE TABLE worldcup_candidate (
  candidate_id  NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
  add_method    VARCHAR2(10 CHAR) NOT NULL,
  worldcup_id   NUMBER(10)        NOT NULL,
  version_id    NUMBER(10)        NOT NULL,
  CONSTRAINT pk_worldcup_candidate   PRIMARY KEY (candidate_id),
  CONSTRAINT uq_candidate_version    UNIQUE (worldcup_id, version_id),
  -- participation의 복합 FK(winner_candidate_id, worldcup_id)가 참조할 대상
  CONSTRAINT uq_candidate_worldcup   UNIQUE (candidate_id, worldcup_id),
  CONSTRAINT ck_candidate_add_method CHECK (add_method IN ('AUTO', 'MANUAL')),
  CONSTRAINT fk_candidate_worldcup   FOREIGN KEY (worldcup_id) REFERENCES worldcup (worldcup_id),
  -- 후보로 쓰인 학생 버전은 삭제 거부(요구 18)
  CONSTRAINT fk_candidate_version    FOREIGN KEY (version_id)  REFERENCES student_version (version_id)
);


-- ---------------------------------------------------------------------
-- 12. 월드컵참여기록
-- ---------------------------------------------------------------------
CREATE TABLE participation (
  record_id            NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
  started_at           TIMESTAMP         DEFAULT SYSTIMESTAMP  NOT NULL,
  completed_at         TIMESTAMP,
  last_saved_at        TIMESTAMP         DEFAULT SYSTIMESTAMP  NOT NULL,
  status               VARCHAR2(12 CHAR) DEFAULT 'IN_PROGRESS' NOT NULL,
  is_result_shared     CHAR(1)           DEFAULT 'N'           NOT NULL,
  member_id            VARCHAR2(20 CHAR)                       NOT NULL,
  worldcup_id          NUMBER(10)                              NOT NULL,
  winner_candidate_id  NUMBER(10),
  CONSTRAINT pk_participation          PRIMARY KEY (record_id),
  CONSTRAINT ck_participation_status   CHECK (status IN ('IN_PROGRESS', 'COMPLETED')),
  CONSTRAINT ck_participation_shared   CHECK (is_result_shared IN ('Y', 'N')),
  -- 완료 상태와 완료일시·우승 후보는 항상 함께 존재(요구 60)
  CONSTRAINT ck_participation_complete CHECK (
       (status = 'IN_PROGRESS' AND completed_at IS NULL     AND winner_candidate_id IS NULL)
    OR (status = 'COMPLETED'   AND completed_at IS NOT NULL AND winner_candidate_id IS NOT NULL)),
  -- 완료 기록만 공유(요구 65)
  CONSTRAINT ck_participation_share_done CHECK (is_result_shared = 'N' OR status = 'COMPLETED'),
  CONSTRAINT fk_participation_member   FOREIGN KEY (member_id)   REFERENCES member (member_id),
  CONSTRAINT fk_participation_worldcup FOREIGN KEY (worldcup_id) REFERENCES worldcup (worldcup_id),
  -- 우승 후보는 이 월드컵의 후보여야 함
  CONSTRAINT fk_participation_winner   FOREIGN KEY (winner_candidate_id, worldcup_id)
                                       REFERENCES worldcup_candidate (candidate_id, worldcup_id)
);

-- 회원·월드컵당 진행 중 기록 최대 1건(요구 54)
CREATE UNIQUE INDEX uq_participation_in_progress
  ON participation (CASE WHEN status = 'IN_PROGRESS' THEN member_id   END,
                    CASE WHEN status = 'IN_PROGRESS' THEN worldcup_id END);


-- ---------------------------------------------------------------------
-- 13. 월드컵대결
-- ---------------------------------------------------------------------
CREATE TABLE worldcup_match (
  match_id             NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
  round_size           NUMBER(3)  NOT NULL,
  match_order          NUMBER(3)  NOT NULL,
  record_id            NUMBER(19) NOT NULL,
  first_candidate_id   NUMBER(10) NOT NULL,
  second_candidate_id  NUMBER(10) NOT NULL,
  winner_candidate_id  NUMBER(10),
  CONSTRAINT pk_worldcup_match       PRIMARY KEY (match_id),
  CONSTRAINT uq_match_position       UNIQUE (record_id, round_size, match_order),
  CONSTRAINT ck_match_round          CHECK (round_size IN (2, 4, 8, 16, 32, 64, 128, 256)),
  CONSTRAINT ck_match_order          CHECK (match_order BETWEEN 1 AND round_size / 2),
  CONSTRAINT ck_match_two_candidates CHECK (first_candidate_id <> second_candidate_id),
  CONSTRAINT ck_match_winner         CHECK (winner_candidate_id IS NULL
                                            OR winner_candidate_id IN (first_candidate_id, second_candidate_id)),
  CONSTRAINT fk_match_record         FOREIGN KEY (record_id)           REFERENCES participation (record_id) ON DELETE CASCADE,
  CONSTRAINT fk_match_first          FOREIGN KEY (first_candidate_id)  REFERENCES worldcup_candidate (candidate_id),
  CONSTRAINT fk_match_second         FOREIGN KEY (second_candidate_id) REFERENCES worldcup_candidate (candidate_id),
  CONSTRAINT fk_match_winner         FOREIGN KEY (winner_candidate_id) REFERENCES worldcup_candidate (candidate_id)
);


-- ---------------------------------------------------------------------
-- 인덱스 (명세서 9장)
-- UQ 인덱스의 첫 컬럼과 겹치는 FK는 따로 만들지 않는다.
-- ---------------------------------------------------------------------
CREATE INDEX ix_student_school           ON student (school_id);
CREATE INDEX ix_student_club             ON student (club_id, school_id);
CREATE INDEX ix_like_member_created      ON version_like (member_id, created_at);
CREATE INDEX ix_like_version             ON version_like (version_id);
CREATE INDEX ix_favorite_member_created  ON version_favorite (member_id, created_at);
CREATE INDEX ix_favorite_version         ON version_favorite (version_id);
CREATE INDEX ix_worldcup_visibility      ON worldcup (visibility, first_published_at);
CREATE INDEX ix_worldcup_member          ON worldcup (member_id);
CREATE INDEX ix_candidate_version        ON worldcup_candidate (version_id);
CREATE INDEX ix_participation_worldcup   ON participation (worldcup_id, status);
CREATE INDEX ix_participation_member     ON participation (member_id, status);
CREATE INDEX ix_participation_winner     ON participation (winner_candidate_id, worldcup_id);
CREATE INDEX ix_match_first              ON worldcup_match (first_candidate_id);
CREATE INDEX ix_match_second             ON worldcup_match (second_candidate_id);
CREATE INDEX ix_match_winner             ON worldcup_match (winner_candidate_id);


